// Social button background styles (gradients must extend to 100% to fill the circle)
const SOCIAL_BACKGROUNDS: Record<string, string> = {
    x: "#141414",
    twitter: "#141414",
    tiktok: "#141414",
    spotify: "#1ED760",
    instagram: "radial-gradient(circle at 33% 100%, #FFDD55 0%, #FF994A 10%, #FF7644 20%, #FF543E 30%, #F14D59 40%, #E44675 55%, #C837AB 70%, #C837AB 100%)",
    telegram: "linear-gradient(180deg, #2AABEE 0%, #229ED9 100%)",
    facebook: "#0866FF",
    google: "#F3F8FF",
    twitch: "#9146FF",
    discord: "#5865F2",
    linkedin: "#0A66C2",
    zoom: "#2D8CFF",
    soundcloud: "linear-gradient(135deg, #F79810 0%, #F8310E 100%)",
    suno: "#141414",
}

interface SocialButtonProps {
    platform: keyof typeof SOCIAL_BACKGROUNDS
    icon?: React.ReactNode
    onClick?: () => void
    className?: string
}

/**
 * SocialButton - A 42x42px circular button for social platforms
 *
 * Features 2px light-glass-20 border and platform-specific background colors/gradients.
 */
export function SocialButton({ platform, icon, onClick, className }: SocialButtonProps) {
    const background = SOCIAL_BACKGROUNDS[platform.toLowerCase()] || "#141414"
    const isGradient = background.includes("gradient")
    const needsWhiteIcon = platform.toLowerCase() !== "google"

    return (
        <button
            type="button"
            onClick={onClick}
            className={cn(
                "relative size-[42px] rounded-full flex items-center justify-center overflow-hidden",
                needsWhiteIcon && "text-white",
                onClick && "cursor-pointer",
                className
            )}
            style={{
                background: isGradient ? background : undefined,
                backgroundColor: !isGradient ? background : undefined,
                border: "1px solid var(--color-light-glass-20)",
            }}
        >
            {icon}
        </button>
    )
}
